css:
.loader {
  position: relative;
  width: 50px;
  height: 50px;
  border-radius: 50%;
  border: 3px solid #6366f1;
  box-sizing: border-box;
}
.loader::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  width: 6px;
  height: 6px;
  margin: -3px 0 0 -3px;
  border-radius: 50%;
  background: #4338ca;
  z-index: 2;
}
.loader b, .loader i {
  position: absolute;
  left: 50%;
  bottom: 50%;
  border-radius: 2px;
  transform-origin: bottom center;
}
.loader b {
  width: 3px;
  height: 12px;
  margin-left: -1.5px;
  background: #4338ca;
  animation: spin 6s linear infinite;
}
.loader i {
  width: 2px;
  height: 18px;
  margin-left: -1px;
  background: #6366f1;
  animation: spin 2s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }
